-- TOTAL PROYECTO B: 26464.866000
-- ============================================================
-- 8b. Totales de capítulos del escenario B (write-through, DM §11)
--      Raíces = suma de subcapítulos; subcapítulos = suma de rubros.
-- ============================================================
UPDATE capitulo c SET total = COALESCE((
  SELECT SUM(r.precio_total) FROM rubro r WHERE r.capitulo_id = c.id
), 0)
WHERE c.presupuesto_id = (SELECT id FROM presupuesto WHERE proyecto_id = (SELECT id FROM proyecto WHERE nombre_proyecto = 'Rehabilitación de consultorios UCE') AND version = 1)
  AND c.parent_id IS NOT NULL;

UPDATE capitulo c SET total = COALESCE((
  SELECT SUM(sub.total) FROM capitulo sub WHERE sub.parent_id = c.id
), 0)
WHERE c.presupuesto_id = (SELECT id FROM presupuesto WHERE proyecto_id = (SELECT id FROM proyecto WHERE nombre_proyecto = 'Rehabilitación de consultorios UCE') AND version = 1)
  AND c.parent_id IS NULL;

-- Subtotales de sección del escenario B (write-through, DM §9/§11)
UPDATE apu_seccion s SET subtotal = COALESCE((
  SELECT SUM(d.costo) FROM apu_detalle d WHERE d.seccion_id = s.id
), 0)
WHERE s.apu_id IN (
  SELECT a.id FROM apu a
  WHERE a.presupuesto_id = (SELECT id FROM presupuesto WHERE proyecto_id = (SELECT id FROM proyecto WHERE nombre_proyecto = 'Rehabilitación de consultorios UCE') AND version = 1)
);
